import { useState } from "react";
import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import { Icon } from "@/registry/erbium/ui/icon";

import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
  InputGroupTextarea,
} from "@/registry/erbium/ui/input-group";

export function InputGroupBlockStart() {
  const [code, setCode] = useState("console.log('Hello, world!');");

  return (
    <FieldGroup className="max-w-sm">
      <Field>
        <FieldLabel>Input</FieldLabel>
        <InputGroup className="h-auto">
          <InputGroupInput placeholder="Enter your name" />
          <InputGroupAddon align="block-start">
            <InputGroupText>Full Name</InputGroupText>
          </InputGroupAddon>
        </InputGroup>
        <FieldDescription>Header positioned above the input.</FieldDescription>
      </Field>
      <Field>
        <FieldLabel>Textarea</FieldLabel>
        <InputGroup>
          <InputGroupTextarea
            value={code}
            onChange={(event) => {
              setCode(event.target.value);
            }}
            placeholder="console.log('Hello, world!');"
            className="font-mono text-caption"
          />
          <InputGroupAddon align="block-start">
            <Icon name="file-code" className="text-muted-foreground" />
            <InputGroupText className="font-mono">script.js</InputGroupText>
            <CopyButton
              value={code}
              aria-label="Copy script"
              render={<InputGroupButton size="icon-xs" className="ml-auto" />}
            />
          </InputGroupAddon>
        </InputGroup>
        <FieldDescription>Header positioned above the textarea.</FieldDescription>
      </Field>
    </FieldGroup>
  );
}

import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import * as React from "react";
import { Icon } from "@/registry/erbium/ui/icon";

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/registry/erbium/ui/input-group";
import { Popover, PopoverContent, PopoverTrigger } from "@/registry/erbium/ui/popover";

export default function InputGroupButtonExample() {
  const [isFavorite, setIsFavorite] = React.useState(false);

  return (
    <div className="grid w-full max-w-sm gap-section">
      <InputGroup>
        <InputGroupInput value="https://example.com/john-doe" readOnly />
        <InputGroupAddon align="inline-end">
          <CopyButton
            value="https://example.com/john-doe"
            aria-label="Copy profile URL"
            render={<InputGroupButton size="icon-xs" />}
          />
        </InputGroupAddon>
      </InputGroup>
      <InputGroup className="[--radius:9999px]">
        <InputGroupAddon>
          <Popover>
            <PopoverTrigger
              render={
                <InputGroupButton
                  aria-label="Connection information"
                  variant="secondary"
                  size="icon-xs"
                >
                  <Icon name="info" />
                </InputGroupButton>
              }
            />
            <PopoverContent align="start" className="flex flex-col gap-1 rounded-xl text-caption">
              <p className="font-medium">Your connection is not secure.</p>
              <p>You should not enter any sensitive information on this site.</p>
            </PopoverContent>
          </Popover>
        </InputGroupAddon>
        <InputGroupAddon className="pl-1.5 text-muted-foreground">https://</InputGroupAddon>
        <InputGroupInput id="input-secure-19" />
        <InputGroupAddon align="inline-end">
          <InputGroupButton
            onClick={() => {
              setIsFavorite(!isFavorite);
            }}
            size="icon-xs"
          >
            <Icon
              name="star"
              data-favorite={isFavorite}
              className="data-[favorite=true]:fill-info data-[favorite=true]:stroke-info"
            />
          </InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
      <InputGroup>
        <InputGroupInput placeholder="Type to search..." />
        <InputGroupAddon align="inline-end">
          <InputGroupButton variant="secondary">Search</InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
    </div>
  );
}

import TextareaAutosize from "react-textarea-autosize";

import { InputGroup, InputGroupAddon, InputGroupButton } from "@/registry/erbium/ui/input-group";

export default function InputGroupCustom() {
  return (
    <div className="grid w-full max-w-sm gap-section">
      <InputGroup>
        <TextareaAutosize
          data-slot="input-group-control"
          className="flex field-sizing-content min-h-16 w-full resize-none rounded-md bg-transparent px-3 py-2.5 text-body transition-field outline-none md:text-caption"
          placeholder="Autoresize textarea..."
        />
        <InputGroupAddon align="block-end">
          <InputGroupButton className="ml-auto" size="sm" variant="default">
            Submit
          </InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
    </div>
  );
}

